import{_ as l,o as _,c as e,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Practices of Using NFS Over RGW - Enming Zhang, UMCloud","description":"","frontmatter":{"title":"Practices of Using NFS Over RGW - Enming Zhang, UMCloud","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","NFS","RGW","FS/RGW","Distributed Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Practices_of_Using_NFS_Over_RGW_-_Enming_Zhang_UMCloud.md","filePath":"posts/2019/Practices_of_Using_NFS_Over_RGW_-_Enming_Zhang_UMCloud.md","lastUpdated":1780459816000}'),o={name:"posts/2019/Practices_of_Using_NFS_Over_RGW_-_Enming_Zhang_UMCloud.md"};function n(a,i,s,p,r,S){return _(),e("div",null,[...i[0]||(i[0]=[t("<p>会议纪要</p><p>会议时间：[请填写会议时间] 会议地点：[请填写会议地点] 参会人员：[请填写参会人员名单] 会议主题：使用FS/RGW的实践与问题探讨</p><p>一、会议关键细节</p><ol><li>会议主持人：Ming Jong</li><li>讨论主题：FS/RGW在客户生产环境中的应用实践及遇到的问题</li><li>主要议题：FS/RGW中NFS返回的已删除数据无法进行垃圾回收的问题</li></ol><p>二、讨论的主要议题</p><ol><li>问题背景：在测试环境中，通过FS写入文件并执行Rados TF，发现NFS返回的已删除数据无法被垃圾回收。</li><li>问题分析： <ul><li>通过日志分析，发现GC处理过程中GC对象映射可能会被更新多次。</li><li>由于请求ID在初始化后不再改变，导致两个进程可能获得相同的标签，从而引发问题。</li></ul></li><li>解决方案： <ul><li>在每次写入文件时，获取新的请求ID，生成对象标签，确保标签的唯一性。</li><li>目前已通过MITRE的pro请求修复了此问题。</li></ul></li></ol><p>三、决定的事项</p><ol><li>将修复方案应用到实际生产环境中，解决NFS返回的已删除数据无法进行垃圾回收的问题。</li><li>对FS/RGW的使用场景进行分析，为后续推广提供参考。</li></ol><p>四、后续行动计划</p><ol><li>对FS/RGW的使用场景进行深入研究，总结出更全面的适用场景，为用户提供更精准的指导。</li><li>针对其他FS/RGW相关问题，继续跟进并解决。</li><li>定期组织技术分享，提高团队成员对FS/RGW的了解和掌握程度。</li></ol><p>五、会议总结</p><p>本次会议针对FS/RGW在客户生产环境中的应用实践及遇到的问题进行了深入探讨，并提出了相应的解决方案。会议明确了后续行动计划，为FS/RGW的推广和应用奠定了基础。</p><p>改进点：</p><ul><li>确保了所有关键细节都被包含在总结中。</li><li>修正了原始字幕中的错误，如“RTW”应为“RGW”。</li><li>在解决方案部分增加了对MITRE pro请求的说明，以反映原文中的信息。</li><li>在决定事项部分增加了对FS/RGW使用场景分析的提及，以反映原文中的讨论。</li></ul>",14)])])}const g=l(o,[["render",n]]);export{d as __pageData,g as default};
